mapper.select:
SELECT tdm14_task_type_id AS task_type_id , tdm14_task_class_cd AS task_class_code , f_cdnm('TdmTaskClassCode', tdm14_task_class_cd, tdm14_company_id, f_today())||'('||tdm14_task_class_cd||')' AS task_class_name , tdm14_task_type_cd AS task_type_code , tdm14_task_type_nm AS task_type_name , tdm14_use_yn AS use_yn FROM ( SELECT * , SUBSTR(tdm14_task_type_cd,1,1) AS tdm14_task_class_cd FROM tdm14_task_type WHERE tdm14_company_id = #{companyId}
AND COALESCE(tdm14_use_yn, 'false') = 'true'
) t WHERE tdm14_task_class_cd LIKE #{taskClassCode} ORDER BY tdm14_task_class_cd, tdm14_task_type_cd

SELECT count(*)
  FROM tdm14_task_type
 WHERE tdm14_company_id     = #{companyId}
   AND tdm14_task_type_cd   = #{taskTypeCode}
   AND tdm14_task_type_id  != #{taskTypeId}

SELECT count(*)
  FROM tdm10_task
 WHERE tdm10_company_id     = #{companyId}
   AND tdm10_task_type_cd   = #{taskTypeCode}

SELECT tdm14_task_type_cd
  FROM tdm14_task_type
 WHERE tdm14_task_type_id = #{taskTypeId}
   AND tdm14_company_id   = #{companyId}

mapper.update:
UPDATE tdm14_task_type
   SET tdm14_task_type_cd = #{row.taskTypeCode}
     , tdm14_task_type_nm = #{row.taskTypeName}
     , tdm14_use_yn       = #{row.useYn}
     , tdm14_upd_nm       = #{updName}
     , tdm14_upd_date     = f_sysdate()
 WHERE tdm14_task_type_id = #{row.taskTypeId}
   AND tdm14_company_id   = #{companyId}

mapper.delete:
DELETE FROM tdm14_task_type
 WHERE tdm14_company_id = #{companyId}
   AND tdm14_task_type_id IN
#{id}
